{
  "criteria": [
    {
      "id": "C1",
      "score": 0.5,
      "reason": "The report provides an explicit assumption-by-assumption read-through and appropriately notes that the sources cannot fully validate the model. However, it materially misreads prediction.csv by claiming zero interest expense and uninterrupted positive net income from Year 1, and by presenting CAC/LTV ranges that apply only within 2028.",
      "report_quote": "- **Revenue ramp $1.85M (2024) → ~$14.9M (2028):** ~8× in four years implies ~68% CAGR. The corpus confirms a hot funding/demand environment (D0040, D0167, D0191) but contains no benchmark showing typical AI-startup revenue growth at this rate; treat as ambitious-but-unverifiable against this collection."
    },
    {
      "id": "C2",
      "score": 1,
      "reason": "The report inspects the attached outline, correctly identifies that its target industry and company fields are placeholders, scopes the work to the general AI industry, and broadly covers the outline's market-overview, competitive-landscape, challenge, and future-trend components.",
      "report_quote": "The attached report outline (tex.pdf) is a template with `[Target Industry]`/`[Your Company Name]` placeholders, so this brief treats \"the space\" as the general AI industry. If a narrower vertical is intended, the corpus has limited vertical-specific data (healthcare is the best-covered vertical — D0009)."
    },
    {
      "id": "C3",
      "score": 1,
      "reason": "The response is an organized, nontechnical brief with concise headings and bullets rather than an exhaustive technical analysis.",
      "report_quote": "## 1. Overview\n\n- AI adoption is broad but shallow."
    },
    {
      "id": "C4",
      "score": 1,
      "reason": "The report names multiple startups and describes their products, funding, customers, and competitive positioning.",
      "report_quote": "- **VoiceRun** — platform for developers/coding agents to build, test, and deploy enterprise voice agents; closed a $5.5M seed round led by Flybridge Capital (Jan 2026). Competes between no-code builders (Bland, ReTell AI) and developer frameworks (LiveKit, Pipecat). The article notes AI-agent startups \"nabbed billions of dollars\" last year. (D0040)\n- **Symbolic.ai** — AI platform for journalism workflows (newsletter creation, transcription, fact-checking, headline optimization); founded by former eBay CEO Devin Wenig and Ars Technica co-founder Jon Stokes; signed a deal with News Corp / Dow Jones Newswires; claims productivity gains up to 90% on complex research tasks. (D0069)"
    },
    {
      "id": "C5",
      "score": 1,
      "reason": "The report supplies adoption, enterprise-impact, investment, adjacent-market forecast, employment, and bubble-risk data to indicate both health and direction.",
      "report_quote": "- Adjacent markets that ride the AI wave show strong forecasts in the corpus: public cloud $935.7B (2025) → $2.73T by 2033 at 14.7% CAGR; customer data platforms $8.26B → $58.4B at 27.8% CAGR; data protection-as-a-service $28.07B → $179.1B at 26.8% CAGR. (D0093, D0013)"
    },
    {
      "id": "C6",
      "score": 1,
      "reason": "The report includes a dedicated section flagging fragmented AI regulation, the EU AI Act, a possible AI investment correction, IP litigation/licensing, workforce-policy shifts, and privacy obligations.",
      "report_quote": "- **EU AI Act** — imposes risk-tiered transparency requirements (e.g., high-risk systems such as résumé-ranking must document capabilities, limitations, data lineage, decision logic). Drives demand for explainability/observability tooling. (D0050)"
    }
  ],
  "sampled_claims": [
    {
      "report_quote": "McKinsey's latest State of AI survey reports 88% of organizations use AI regularly in at least one business function (up from 78% a year earlier), yet roughly two-thirds remain in experimentation/pilot mode and only ~one-third have begun scaling.",
      "source_id": "D0074",
      "source_quote": "The share of respondents saying their organizations are using AI in at least one business function has increased since our research last year: 88 percent report regular AI use in at least one business function, compared with 78 percent a year ago. But at the enterprise level, the majority are still in the experimenting or piloting stages (Exhibit 1), with approximately one-third reporting that their companies have begun to scale their AI programs.",
      "verdict": "supported",
      "reason": "The source directly supports the 88%, 78%, majority-piloting, and approximately one-third scaling figures."
    },
    {
      "report_quote": "public cloud $935.7B (2025) → $2.73T by 2033 at 14.7% CAGR",
      "source_id": "D0093",
      "source_quote": "The global public cloud market size was estimated at USD 935.71 billion in 2025 and is projected to reach USD 2,729.95 billion by 2033, growing at a CAGR of 14.7% from 2026 to 2033.",
      "verdict": "supported",
      "reason": "The report's rounded $935.7B and $2.73T figures and the 14.7% CAGR match the source."
    },
    {
      "report_quote": "EU AI Act — imposes risk-tiered transparency requirements (e.g., high-risk systems such as résumé-ranking must document capabilities, limitations, data lineage, decision logic).",
      "source_id": "D0050",
      "source_quote": "The EU AI Act, for example, imposes specific transparency requirements for different AI use cases classified according to its risk-based framework. For example, in the case of high-risk AI systems—such as systems used in recruitment, like résumé-ranking software—organizations are required to provide information about the system’s capabilities, limitations, data lineage, and the logic behind the decisions it makes.",
      "verdict": "supported",
      "reason": "The source explicitly supports both the risk-based transparency framework and the résumé-ranking disclosure example."
    },
    {
      "report_quote": "Declining CAC ($80→$65) with rising LTV ($2,600→$2,900)",
      "source_id": "user_file:prediction.csv",
      "source_quote": "2024,Customer Acquisition Cost (CAC),250,230,210,190,\n2024,Customer Lifetime Value (LTV),1000,1100,1200,1300,\n2028,Customer Acquisition Cost (CAC),80,75,70,65,\n2028,Customer Lifetime Value (LTV),2600,2700,2800,2900,",
      "verdict": "contradicted",
      "reason": "The quoted endpoints apply only within 2028. Across the projection period, CAC declines from 250 to 65 and LTV rises from 1,000 to 2,900, so the unqualified ranges materially misrepresent the CSV."
    },
    {
      "report_quote": "Zero interest expense, zero taxes, uninterrupted positive net income from Year 1",
      "source_id": "user_file:prediction.csv",
      "source_quote": "2024,Interest Expense,5000,5000,5000,5000,20000\n2024,Taxes,0,0,0,0,0\n2024,Net Income,-135000,-80500,11500,66000,-138000\n2025,Interest Expense,4000,3000,2000,1000,10000",
      "verdict": "contradicted",
      "reason": "Taxes are zero, but interest expense is positive in 2024 and 2025, and 2024 annual net income is negative. The compound claim is therefore false."
    }
  ]
}
